from django.db import migrations, models

# Labels of the fixed software-item choices used before 0003. Stored codes become these labels,
# which is what users already saw, so no record changes meaning.
LEGACY_LABELS = {"asr": "ASR", "virtual_agent": "Virtual agent", "scoring_model": "Scoring model",
                 "web_app": "Web app", "reporting": "Reporting", "infrastructure": "Infrastructure"}


def relabel_and_fill_device_lists(apps, schema_editor):
    """Replace codes with labels and give each device the items its data already uses."""
    Device = apps.get_model("qms", "Device")
    used = {}
    for model_name in ("Record", "Hazard"):
        model = apps.get_model("qms", model_name)
        for code, label in LEGACY_LABELS.items():
            model.objects.filter(software_item=code).update(software_item=label)
        for device_id, item in model.objects.exclude(software_item="") \
                .values_list("device_id", "software_item").distinct():
            used.setdefault(device_id, set()).add(item)
    SoupItem = apps.get_model("qms", "SoupItem")
    for code, label in LEGACY_LABELS.items():
        SoupItem.objects.filter(software_item=code).update(software_item=label)
    for soup in SoupItem.objects.exclude(software_item=""):
        for device_id in soup.devices.values_list("pk", flat=True):
            used.setdefault(device_id, set()).add(soup.software_item)
    order = list(LEGACY_LABELS.values())
    for device in Device.objects.filter(pk__in=used):
        items = sorted(used[device.pk], key=lambda i: (order.index(i) if i in order else 99, i))
        Device.objects.filter(pk=device.pk).update(software_items="\n".join(items))


